blocking: This class only checks ctx.effective_team_id from the dataclass. It never invokes _apply_team_filter against a parent/child setup, so neither the cached-parent branch (manager.py:81) nor the subquery branch (manager.py:83) runs against real rows. The most complex SQL in the file has zero behavioral coverage. A regression that scopes a child team's reads to the wrong parent, or drops the root-team OR-fallback, ships green.
Add three tests that go through the public manager path: parent cached, parent uncached forcing the subquery branch, root team for the OR-fallback. Sketch:
def test_apply_team_filter_uses_cached_parent_team(self):
    parent = Team.objects.create(organization=self.organization, name="Parent")
    child = Team.objects.create(organization=self.organization, name="Child", parent_team=parent)
    FeatureFlag.objects.create(team=parent, key="parent-flag", created_by=self.user)
    FeatureFlag.objects.create(team=child, key="child-flag", created_by=self.user)
    with team_scope(child.id, parent_team_id=parent.id):
        keys = set(self._make_manager().get_queryset().values_list("key", flat=True))
    assert keys == {"parent-flag"}

def test_apply_team_filter_subquery_path_when_cache_missing(self):
    # same setup, but no parent_team_id cached, forces the subquery branch
    with team_scope(child.id):
        keys = set(self._make_manager().get_queryset().values_list("key", flat=True))
    assert keys == {"parent-flag"}

def test_apply_team_filter_root_team_falls_back_to_own_id(self):
    FeatureFlag.objects.create(team=self.team, key="root-flag", created_by=self.user)
    with team_scope(self.team.id):
        keys = set(self._make_manager().get_queryset().values_list("key", flat=True))
    assert keys == {"root-flag"}

